-- ============================================================
-- Contenido inicial de PokeDoc: 13 guías oficiales.
--
-- Seguro de ejecutar más de una vez: usa "on conflict (slug) do
-- nothing", así que si vuelves a lanzarlo no duplica ni pisa nada
-- de lo que ya tengas. Tampoco toca ninguna guía existente.
--
-- Las guías entran como OFICIALES (author_id = null, review_status
-- 'approved') y YA PUBLICADAS. Si prefieres revisarlas antes de que
-- se vean, cambia `now()` por `null` en la columna published_at de
-- la sentencia de abajo y luego publícalas desde /admin.
--
-- Al final se recalcula categories.guide_count, que no tiene
-- trigger en la base de datos y si no se queda desincronizado.
-- ============================================================

begin;

insert into guides (
  slug, title, description, category_id, cover_emoji, level, guide_rarity,
  xp_reward, estimated_mins, tags, search_content, blocks, reference_blocks,
  is_pro, reference_unlocked_by_default, review_status, author_id,
  collection_order, published_at, created_at
)
select
  s.slug, s.title, s.description, c.id, s.cover_emoji, s.level, s.guide_rarity,
  s.xp_reward, s.estimated_mins, s.tags, s.search_content,
  s.blocks::jsonb, s.reference_blocks::jsonb,
  false,   -- is_pro: contenido abierto
  true,    -- reference_unlocked_by_default: la documentación se lee sin hacer el curso
  'approved',
  null,    -- author_id null = guía oficial (la web muestra "Guía oficial")
  0,
  now(),   -- published_at: ya visible
  now()
from (values
  ('6-chequeos-carta-falsa', 'Los 6 chequeos para saber si una carta es falsa', 'Una rutina rápida que puedes hacer con la carta en la mano, sin lupa ni herramientas raras.', 'fake_detection', '🔍', 'beginner', 'bronze', 25, 8, array['falsificaciones', 'básico', 'autenticar']::text[], 'carta falsa fake autenticar detectar reconocer original', '[{"type": "hook", "emoji": "🔍", "headline": "¿Sabrías decir si esta carta es falsa?", "subtext": "No hace falta lupa ni experiencia. Con seis chequeos rápidos se cae la mayoría de falsificaciones."}, {"type": "truefalse", "statement": "Si una carta falla uno de los chequeos, ya se puede dar por falsa.", "is_true": false, "explanation": "No. Una carta auténtica puede fallar un chequeo por desgaste o por una tirada rara. Lo que delata a una falsificación es acumular varias señales a la vez."}, {"type": "quiz", "question": "Miras el canto de una carta de perfil y lo ves blanco y uniforme, sin ninguna línea oscura. ¿Qué significa?", "options": ["Es normal, el núcleo solo se ve si cortas la carta", "Mala señal: las auténticas llevan un núcleo negro entre capas", "Significa que es de primera edición", "Solo indica que la carta está desgastada"], "correct_index": 1, "explanation": "Una carta auténtica es un sándwich de capas con un núcleo negro en medio. Un canto blanco o gris uniforme es una de las señales más fiables de falsificación."}, {"type": "fillblank", "before": "El chequeo más rentable es el reverso azul, porque es", "after": "en millones de cartas y cualquier desviación canta.", "options": ["idéntico", "distinto en cada set", "opcional", "holográfico"], "correct_option": "idéntico", "explanation": "Justo por ser siempre igual, cualquier variación de tono o nitidez en el reverso salta a la vista."}, {"type": "match", "title": "Relaciona cada chequeo con lo que delata a una falsificación", "pairs": [{"left": "Textura", "right": "Superficie completamente lisa y brillante"}, {"left": "Holo", "right": "Brillo plano que no cambia al inclinar la carta"}, {"left": "Tipografía", "right": "Línea de copyright incompleta o mal escrita"}, {"left": "Número de set", "right": "Ese Pokémon no existe con ese número"}]}, {"type": "order", "title": "Ordena la rutina, de lo más rápido y no invasivo a lo último", "items": ["Comparar el reverso azul con una carta que sepas auténtica", "Revisar tipografía, HP y línea de copyright", "Pasar el dedo por la superficie y buscar el tramado", "Mirar el canto de perfil buscando el núcleo negro", "Buscar el número de coleccionista para confirmar que existe en ese set"]}, {"type": "truefalse", "statement": "Un Pokémon con 3000 HP es una falsificación especialmente bien hecha.", "is_true": false, "explanation": "Al contrario: significa que ni siquiera intentan imitar una carta real. Eso es mercancía de bazar, no una falsificación cuidada."}, {"type": "reward", "next_guide_slug": "test-luz-rip-test"}]', '[{"type": "richtext", "html": "<h2>Antes de empezar</h2>\n<p>Ninguna de estas señales es definitiva por sí sola. Una carta auténtica puede fallar un chequeo por desgaste o por una tirada rara de impresión. Lo que delata a una falsificación es <strong>acumular varias señales a la vez</strong>. Ve marcándolas mentalmente y decide con el conjunto.</p>\n<p>Si puedes, ten al lado una carta que sepas seguro que es auténtica, de la misma época. Comparar es muchísimo más fiable que juzgar a ciegas.</p>\n\n<h2>1. El reverso azul</h2>\n<p>Es el chequeo más rentable porque el reverso es idéntico en millones de cartas y cualquier desviación canta. Fíjate en el tono del azul: las falsificaciones suelen irse a un azul más morado, más apagado o demasiado saturado.</p>\n<p>Mira también el círculo central con la Poké Ball y las siluetas de los Pokémon del fondo. En las falsas es habitual que estén <strong>borrosas, con los bordes emborronados</strong> o descentradas respecto al recuadro.</p>\n\n<h2>2. La tipografía</h2>\n<p>Es donde más se pillan las falsificaciones baratas. Revisa:</p>\n<ul>\n<li>El número de HP arriba a la derecha: grosor y separación de los dígitos.</li>\n<li>La línea de copyright de abajo (<em>©</em> + año + Pokémon / Nintendo / Creatures / GAMEFREAK). En las falsas falta parte, está mal escrita o tiene un año imposible para ese set.</li>\n<li>El texto de los ataques: si se ve pixelado o con los bordes sucios al acercarte, mala señal.</li>\n</ul>\n\n<h2>3. La textura de la superficie</h2>\n<p>Las cartas modernas auténticas tienen un acabado con un patrón de tramado muy fino, casi como tela, que se nota al pasar la yema del dedo y se ve al inclinarlas bajo una luz. Muchas falsificaciones son <strong>completamente lisas y brillantes</strong>, como una foto plastificada.</p>\n\n<h2>4. El holo</h2>\n<p>En una carta holográfica auténtica el efecto tiene un patrón concreto y reacciona al moverla. En las falsas suele ser un brillo plano y uniforme, tipo purpurina, que no cambia con el ángulo. También es típico que el holo <strong>se salga de su zona</strong> e invada el marco o el texto.</p>\n\n<h2>5. Bordes y esquinas</h2>\n<p>Mira el canto de la carta de perfil. Una carta auténtica es un sándwich de capas con un <strong>núcleo negro</strong> en el medio, que a veces se intuye como una línea oscura fina en el borde. Las falsificaciones suelen tener el canto blanco o gris uniforme.</p>\n<p>Las esquinas de fábrica están redondeadas con un radio muy regular. En las falsas es normal ver esquinas más cuadradas, irregulares entre sí, o con la capa superior empezando a separarse.</p>\n\n<h2>6. Coherencia del set</h2>\n<p>Abajo a la derecha hay un número de coleccionista (por ejemplo <em>58/165</em>) y un símbolo de expansión. Búscalo: ese Pokémon tiene que existir <strong>en ese set y con ese número exacto</strong>. Es un chequeo de 20 segundos con el móvil y detecta falsificaciones que visualmente son muy buenas.</p>\n\n<blockquote>Regla práctica: un HP absurdo (500, 1000, 3000), un tipo de carta que no existe o un Pokémon con un arte que no aparece en ninguna base de datos son señales de que ni siquiera intentan imitar una carta real. Eso es mercancía de bazar, no una falsificación cuidada.</blockquote>\n\n<h2>Y si sigues con dudas</h2>\n<p>Antes de recurrir a nada que dañe la carta, prueba con la luz: ver el apartado dedicado al test de la luz y al rip test. Y si la carta es cara, lo sensato es pedir opinión a la comunidad con buenas fotos antes de comprar, no después.</p>"}]'),
  ('test-luz-rip-test', 'El test de la luz y el rip test, bien explicados', 'Dos pruebas que funcionan de verdad. Una es inofensiva y la otra destruye la carta: conviene saber cuál es cuál.', 'fake_detection', '💡', 'beginner', 'bronze', 25, 6, array['falsificaciones', 'autenticar', 'núcleo negro']::text[], 'test luz rip test nucleo negro linterna carta falsa', '[{"type": "hook", "emoji": "💡", "headline": "Una linterna delata más falsificaciones que una lupa", "subtext": "Pero hay una segunda prueba que no tiene vuelta atrás. Vamos a dejar claro cuándo usar cada una."}, {"type": "concept", "emoji": "🥪", "title": "El núcleo negro", "body": "Una carta auténtica son varias capas pegadas con una capa central de tinta negra en medio. Está ahí para que no se transparente la cara por el reverso, y es lo que casi ninguna falsificación reproduce, porque encarece la impresión.", "highlight": "Las dos pruebas de este curso comprueban lo mismo: si ese núcleo está o no está."}, {"type": "quiz", "question": "Apoyas una carta sobre la linterna del móvil a oscuras y se ilumina entera, dejando ver el reverso a través. ¿Qué indica?", "options": ["Que es auténtica: las originales dejan pasar luz", "Nada, el test de la luz no sirve", "Que probablemente le falta el núcleo negro", "Que la carta es de primera edición"], "correct_index": 2, "explanation": "Una carta auténtica deja pasar muy poca luz porque el núcleo negro la bloquea. Si se ilumina entera, lo más probable es que ese núcleo no exista."}, {"type": "truefalse", "statement": "Si una carta supera el test de la luz, ya se puede dar por auténtica.", "is_true": false, "explanation": "No. Las falsificaciones buenas ya incorporan una capa oscura. El test descarta a las malas, pero no garantiza autenticidad."}, {"type": "truefalse", "statement": "El rip test conviene hacerlo antes que los chequeos visuales, porque es el más concluyente.", "is_true": false, "explanation": "Es el más concluyente, pero destruye la carta. Va siempre el último: primero lo visual, luego la luz, y el rip test solo como último recurso."}, {"type": "order", "title": "Ordena las pruebas de menos a más destructiva", "items": ["Chequeos visuales (reverso, tipografía, textura, holo)", "Test de la luz con una linterna", "Rip test sobre una sola carta del lote"]}, {"type": "checklist", "title": "Antes de hacer un rip test, confirma que", "items": ["La carta es tuya", "Ya no puedes devolverla ni reclamar al vendedor", "Estás casi seguro de que el lote es falso", "Vas a sacrificar solo una carta, no todas", "Asumes que si sale auténtica, la has roto para nada"]}, {"type": "reward", "next_guide_slug": "slabs-falsos-verificar"}]', '[{"type": "richtext", "html": "<h2>Por qué funcionan estas dos pruebas</h2>\n<p>Una carta de Pokémon auténtica no es una sola lámina de cartón: son varias capas pegadas, y entre ellas hay una <strong>capa central de tinta negra</strong>. Esa capa existe para que no se transparente la cara por el reverso, y es justo lo que casi ninguna falsificación reproduce, porque encarece la impresión.</p>\n<p>Las dos pruebas de esta guía atacan lo mismo: comprobar si ese núcleo negro está ahí.</p>\n\n<h2>El test de la luz</h2>\n<p>Es el que deberías usar el 99% de las veces, porque <strong>no daña nada</strong>.</p>\n<ol>\n<li>Coge una linterna potente. La del móvil sirve.</li>\n<li>En una habitación a oscuras, apoya la carta directamente sobre la linterna, con la luz por detrás.</li>\n<li>Mira cuánta luz atraviesa.</li>\n</ol>\n<p>Una carta auténtica deja pasar <strong>muy poca luz</strong>: se ve un resplandor tenue en los bordes y poco más, porque el núcleo negro bloquea el paso. Una falsificación suele iluminarse entera, y muchas veces se llega a ver el dibujo del reverso a través de la cara.</p>\n<p>La clave otra vez es comparar. Haz la prueba con una carta que sepas auténtica y con la sospechosa, seguidas, con la misma linterna. La diferencia, cuando la hay, es evidente.</p>\n\n<h3>Dos avisos sobre el test de la luz</h3>\n<ul>\n<li>Las cartas <strong>gruesas o especiales</strong> (algunas de arte completo, cartas de metal, promocionales raras) pueden comportarse distinto. No las juzgues solo por esto.</li>\n<li>Las falsificaciones buenas ya incorporan una capa oscura. Superar el test de la luz <strong>no garantiza</strong> que la carta sea auténtica, solo descarta a las malas.</li>\n</ul>\n\n<h2>El rip test</h2>\n<p>Consiste en rasgar una esquina de la carta para ver el corte transversal. Si es auténtica, aparece una <strong>línea negra nítida</strong> entre dos capas claras, como un sándwich.</p>\n<p>Es la prueba más concluyente que existe sin equipo. También <strong>destruye la carta para siempre</strong>.</p>\n\n<blockquote>Nunca hagas un rip test a una carta que no sea tuya, ni a una que tenga cualquier valor, ni a una que aún puedas devolver. Si la carta resulta ser auténtica, acabas de romper una carta auténtica.</blockquote>\n\n<h3>Cuándo tiene sentido</h3>\n<p>Solo en un caso: ya sabes casi seguro que el lote es falso, no vas a poder devolverlo, y quieres una prueba definitiva. Por ejemplo, para reclamar en una plataforma de venta o para avisar a la comunidad de un vendedor.</p>\n<p>En ese caso, sacrifica <strong>una</strong> carta del lote, no todas, y hazlo por una esquina para que el resto de la carta siga sirviendo como prueba fotográfica.</p>\n\n<h2>El orden correcto</h2>\n<p>Chequeos visuales primero. Luego el test de la luz. El rip test, solo como último recurso y asumiendo que pierdes la carta.</p>"}]'),
  ('slabs-falsos-verificar', 'Slabs falsos: cómo verificar un PSA, CGC o BGS', 'Que venga en una carcasa sellada no significa nada por sí solo. Se falsifican, y cada vez mejor.', 'fake_detection', '🧊', 'intermediate', 'silver', 35, 9, array['falsificaciones', 'gradeo', 'psa', 'slabs']::text[], 'slab falso psa cgc bgs beckett verificar certificado gradeo carcasa', '[{"type": "hook", "emoji": "🧊", "headline": "Está en una carcasa sellada. ¿Eso lo garantiza?", "subtext": "No. Las carcasas se falsifican y se reabren. Vamos a ver cómo comprobarlo en tres pasos."}, {"type": "concept", "emoji": "⚠️", "title": "Dos fraudes distintos", "body": "Slab falso: carcasa y etiqueta imitadas con una carta falsa dentro. Slab manipulado: una carcasa auténtica que se abre con calor, se le cambia la carta por otra peor o falsa, y se vuelve a sellar.", "highlight": "El segundo es más difícil de ver, porque la carcasa sí es original."}, {"type": "order", "title": "Ordena la verificación de un slab", "items": ["Buscar el número de certificado en la web de la casa de gradeo", "Comprobar que la carta descrita es exactamente la que tienes", "Comparar la foto del certificado con tu carta", "Inspeccionar la impresión de la etiqueta", "Revisar la junta de la carcasa buscando restos de pegamento"]}, {"type": "quiz", "question": "Metes el número de certificado en la web de PSA y existe, de la misma carta. ¿Ya está verificado?", "options": ["Sí, si el certificado existe la carta es auténtica", "No: el fraude común es clonar el número de un slab real", "Solo si la nota es 10", "Solo si el slab es reciente"], "correct_index": 1, "explanation": "Clonar el número de un slab real de la misma carta es el fraude más habitual. Por eso hay que comparar también la foto del certificado con la carta que tienes delante."}, {"type": "truefalse", "statement": "Un slab con nota alta muy por debajo del precio de mercado es una buena oportunidad.", "is_true": false, "explanation": "Es una señal de alarma. Quien tiene una carta cara y bien graduada sabe lo que vale; un descuento grande casi siempre esconde algo."}, {"type": "match", "title": "Relaciona cada parte del slab con lo que hay que mirar", "pairs": [{"left": "Etiqueta", "right": "Texto pixelado o tipografía que no cuadra"}, {"left": "Junta de la carcasa", "right": "Restos de pegamento o burbujas"}, {"left": "Número de certificado", "right": "Que la foto del registro sea tu carta"}, {"left": "Precio", "right": "Muy por debajo de mercado sin motivo"}]}, {"type": "checklist", "title": "Comprando un slab a distancia", "items": ["Pedir foto del número de certificado legible", "Verificarlo tú mismo en la web de la casa de gradeo", "Comparar la foto del registro con las fotos del vendedor", "Pedir fotos de la junta de la carcasa", "Desconfiar si el vendedor se resiste a mandarlas"]}, {"type": "reward", "next_guide_slug": "sellado-resellado"}]', '[{"type": "richtext", "html": "<h2>El error de partida</h2>\n<p>Mucha gente baja la guardia delante de una carcasa de gradeo. El razonamiento es \"si está encapsulada y con su etiqueta, alguien la ha autenticado ya\". El problema es que <strong>la carcasa también se falsifica</strong>, y el nivel ha subido mucho en los últimos años.</p>\n<p>Hay dos fraudes distintos y conviene no confundirlos:</p>\n<ul>\n<li><strong>Slab completamente falso</strong>: carcasa y etiqueta imitadas, con una carta falsa dentro.</li>\n<li><strong>Slab manipulado</strong>: una carcasa auténtica que se ha abierto con calor, se le ha cambiado la carta por otra peor o falsa, y se ha vuelto a sellar.</li>\n</ul>\n\n<h2>Paso 1: verifica el número de certificado. Siempre.</h2>\n<p>Cada slab lleva un número de certificado único en la etiqueta. Las tres casas principales tienen un buscador público gratuito donde metes ese número y te devuelve qué carta es, de qué set, y qué nota tiene.</p>\n<p>Esto es lo primero que hay que hacer, antes que cualquier inspección física. Y hay que mirar tres cosas en el resultado:</p>\n<ol>\n<li>Que el certificado <strong>exista</strong>.</li>\n<li>Que la carta que describe sea <strong>exactamente</strong> la que tienes delante: mismo Pokémon, mismo set, mismo número de coleccionista.</li>\n<li>Que la <strong>nota</strong> coincida con la de la etiqueta.</li>\n</ol>\n<p>El fraude más común no es inventarse un número: es <strong>clonar el número de un slab real</strong> de la misma carta. Por eso no basta con que el certificado exista.</p>\n\n<h3>El truco de la foto</h3>\n<p>Las casas de gradeo guardan una imagen de la carta que certificaron. Si el buscador te enseña la foto, compárala con tu carta: el centrado, una marquita, el patrón del holo. Si la carta de la foto no es la tuya, tienes un slab manipulado o clonado.</p>\n\n<h2>Paso 2: la etiqueta</h2>\n<p>La impresión de las etiquetas auténticas es muy limpia. En las falsas suele fallar:</p>\n<ul>\n<li>Texto ligeramente <strong>borroso o pixelado</strong> al acercarte.</li>\n<li>Tipografía con grosores o espaciados que no cuadran.</li>\n<li>Colores del logo apagados o desviados.</li>\n<li>La etiqueta <strong>movida o torcida</strong> dentro de la carcasa.</li>\n</ul>\n<p>PSA incorpora además elementos de seguridad en la etiqueta que cambian según el ángulo. Si en una etiqueta que debería tenerlos no reacciona nada al inclinarla, sospecha.</p>\n\n<h2>Paso 3: la carcasa</h2>\n<p>Una carcasa de fábrica está sellada por ultrasonidos: la unión es uniforme en todo el perímetro. Un slab reabierto y vuelto a pegar casi siempre deja rastro:</p>\n<ul>\n<li>Restos de <strong>pegamento</strong> o cambios de brillo en la junta.</li>\n<li>Zonas con la unión más gruesa, deformada o con burbujas.</li>\n<li>Marcas de herramienta en el borde.</li>\n<li>Una carcasa que <strong>cruje o cede</strong> al apretarla suavemente.</li>\n</ul>\n\n<blockquote>Señal de alarma comercial: un slab con nota alta a un precio muy por debajo del mercado. La gente que tiene una carta cara y bien graduada sabe lo que vale. Un descuento grande casi siempre esconde algo.</blockquote>\n\n<h2>Comprando a distancia</h2>\n<p>Pide siempre <strong>fotos del número de certificado legible</strong> antes de pagar, y verifícalo tú mismo en la web de la casa de gradeo. Un vendedor honesto no tiene ningún problema en mandarlas. El que se resiste, se retrata.</p>"}]'),
  ('empezar-coleccion-sin-arruinarte', 'Cómo empezar tu colección sin arruinarte', 'La decisión que más dinero te ahorra no es dónde compras, sino elegir qué coleccionas antes de gastar el primer euro.', 'conceptos', '🌱', 'beginner', 'bronze', 20, 7, array['primeros pasos', 'presupuesto', 'empezar']::text[], 'empezar coleccion principiante presupuesto sobres etb comprar primera carta', '[{"type": "hook", "emoji": "🌱", "headline": "¿Sobres sueltos para empezar? Casi seguro que no", "subtext": "La decisión que más dinero ahorra se toma antes de gastar el primer euro."}, {"type": "truefalse", "statement": "Si quieres una carta concreta, sale más a cuenta buscarla abriendo sobres que comprarla suelta.", "is_true": false, "explanation": "Casi nunca. Comprar la carta suelta suele salir mucho más barato. Quien abre cajas lo hace porque le gusta abrir, no porque compense."}, {"type": "quiz", "question": "¿Por qué conviene elegir un objetivo de colección concreto al empezar?", "options": ["Porque así no puedes comprar otras cosas", "Porque ''coleccionar Pokémon'' es infinito, y con límites es más barato y se puede terminar", "Porque las cartas suben más de precio", "Porque es obligatorio para vender luego"], "correct_index": 1, "explanation": "Una colección con límites es más barata, más satisfactoria y de hecho se puede completar. Además te deja claro qué es colección y qué es capricho."}, {"type": "fillblank", "before": "Al empezar conviene gastar antes en", "after": "que en cartas, porque es lo que evita que una carta impecable se estropee.", "options": ["protección", "sobres", "carcasas de gradeo", "expositores"], "correct_option": "protección", "explanation": "Unas fundas cuestan poquísimo. Una carta doblada o con las esquinas blancas puede perder la mayor parte de su valor."}, {"type": "match", "title": "Relaciona cada sitio de compra con para qué sirve al empezar", "pairs": [{"left": "Cardmarket", "right": "Cartas sueltas, filtrando por estado"}, {"left": "Tienda local", "right": "Ver la carta antes de comprarla"}, {"left": "Wallapop y Vinted", "right": "Gangas, pero también falsificaciones"}, {"left": "Sobres sueltos", "right": "Diversión de abrir, no construir colección"}]}, {"type": "checklist", "title": "Tu plan de arranque", "items": ["Elegir un objetivo: un Pokémon, un set, una era o un tipo de arte", "Fijar un presupuesto mensual pequeño y constante", "Separarlo en ''colección'' y ''diversión''", "Comprar fundas antes que cartas", "Empezar una lista de lo que ya tienes"]}, {"type": "reward", "next_guide_slug": "glosario-coleccionista"}]', '[{"type": "richtext", "html": "<h2>El error que comete casi todo el mundo</h2>\n<p>Empezar comprando sobres sueltos porque es lo que hay en el estanco de al lado. Es divertido, pero como forma de construir una colección es de las más caras que existen.</p>\n<p>La razón es simple: en un sobre te toca lo que te toca. Si lo que quieres es <strong>una carta concreta</strong>, comprar esa carta suelta casi siempre sale muchísimo más barato que perseguirla abriendo sobres. La gente que abre cajas enteras no lo hace porque salga a cuenta, lo hace porque le gusta abrir.</p>\n<blockquote>Abrir sobres y coleccionar son dos aficiones distintas. Las dos son válidas. Mezclarlas sin darte cuenta es lo que vacía la cartera.</blockquote>\n\n<h2>Primero: elige un objetivo</h2>\n<p>\"Coleccionar Pokémon\" es infinito y por tanto imposible. Una colección con límites es más barata, más satisfactoria y de hecho se puede terminar. Opciones que funcionan bien:</p>\n<ul>\n<li><strong>Un Pokémon</strong>: todas las cartas de Snorlax, por ejemplo. Barato de empezar, se puede alargar toda la vida.</li>\n<li><strong>Un set concreto</strong>: completar una expansión. Tiene meta clara y se nota el avance.</li>\n<li><strong>Una era</strong>: solo cartas de la época de Wizards, o solo de la generación con la que creciste.</li>\n<li><strong>Un tipo de arte</strong>: solo full arts, solo ilustraciones de un artista.</li>\n</ul>\n<p>Elegir uno no te impide comprar otras cosas. Solo hace que sepas qué es colección y qué es capricho.</p>\n\n<h2>Segundo: pon un presupuesto y sepáralo</h2>\n<p>Un presupuesto mensual pequeño y constante rinde mucho más que compras grandes por impulso. Y ayuda separarlo mentalmente en dos:</p>\n<ul>\n<li><strong>Colección</strong>: cartas concretas que te faltan, compradas sueltas.</li>\n<li><strong>Diversión</strong>: sobres para abrir. Aquí asumes de entrada que el valor de lo que salga será menor que lo que pagas.</li>\n</ul>\n\n<h2>Tercero: gasta antes en protección que en cartas</h2>\n<p>Es lo más aburrido de comprar y lo que más dinero te ahorra. Unas fundas cuestan poquísimo y evitan que una carta pase de estado impecable a dañada por guardarla suelta en un cajón. Una carta doblada o con las esquinas blancas puede perder la mayor parte de su valor.</p>\n\n<h2>Dónde comprar al empezar</h2>\n<ol>\n<li><strong>Cardmarket</strong> para cartas sueltas: es la referencia en Europa y te deja filtrar por estado y por vendedores del país.</li>\n<li><strong>Tiendas locales</strong>: pagas algo más, pero ves la carta antes de comprarla y preguntas.</li>\n<li><strong>Wallapop y Vinted</strong>: hay gangas reales y también mucha falsificación. Déjalo para cuando ya sepas distinguir.</li>\n</ol>\n\n<h2>Un consejo que suena tonto</h2>\n<p>Apunta lo que tienes. Una hoja de cálculo basta. Sin lista acabas comprando repetidos y sin saber cuánto llevas gastado, y las dos cosas escuecen.</p>"}]'),
  ('glosario-coleccionista', 'El vocabulario que se usa aquí (y qué significa)', 'Holo, reverse, alt art, slab, NM, sealed... Todo lo que verás en los anuncios, explicado sin dar nada por sabido.', 'conceptos', '📖', 'beginner', 'bronze', 20, 6, array['primeros pasos', 'glosario', 'vocabulario']::text[], 'glosario terminos holo reverse alt art slab sealed NM estado significado', '[{"type": "hook", "emoji": "📖", "headline": "\"Vendo Charizard holo\" — ¿holo o reverse holo?", "subtext": "Casi todos los malentendidos al comprar son de vocabulario. Vamos a quitarlos de en medio."}, {"type": "quiz", "question": "Una carta tiene brillo en todo menos en la ilustración. ¿Qué es?", "options": ["Holo", "Reverse holo", "Full art", "Secret rare"], "correct_index": 1, "explanation": "Reverse holo es justo al revés que holo: el brillo está en todo menos en el dibujo. Casi cualquier carta puede tener versión reverse, incluidas las comunes."}, {"type": "fillblank", "before": "Si el set tiene 185 cartas y la tuya pone 191/185, es una", "after": ", porque su número supera el total del set.", "options": ["secret rare", "reverse holo", "primera edición", "promo"], "correct_option": "secret rare", "explanation": "Las secret rare llevan un número mayor que el total anunciado del set. Es la forma más rápida de identificarlas."}, {"type": "match", "title": "Relaciona cada término con su significado", "pairs": [{"left": "Alt art", "right": "Segunda ilustración distinta de una carta que ya existe"}, {"left": "Slab", "right": "La carcasa sellada de una carta graduada"}, {"left": "Sealed", "right": "Producto sin abrir"}, {"left": "Pull", "right": "Lo que te sale al abrir un sobre"}, {"left": "Shadowless", "right": "Carta temprana sin la sombra del recuadro"}]}, {"type": "order", "title": "Ordena los estados de mejor a peor", "items": ["Mint (M)", "Near Mint (NM)", "Excellent (EX)", "Good (GD)", "Played (PL)", "Poor (PO)"]}, {"type": "truefalse", "statement": "Un proxy es lo mismo que una falsificación.", "is_true": false, "explanation": "Un proxy es una reproducción no oficial para jugar sin gastar, y no es fraude si se vende como lo que es. Sí lo es si alguien te lo cuela como carta real."}, {"type": "reward", "next_guide_slug": "leer-una-carta"}]', '[{"type": "richtext", "html": "<h2>Por qué importa</h2>\n<p>La mayoría de los malentendidos al comprar vienen de vocabulario, no de mala fe. Alguien anuncia una carta como \"holo\" cuando es \"reverse holo\" y el precio cambia por completo. Esto es lo que vas a ver una y otra vez.</p>\n\n<h2>Tipos de brillo</h2>\n<ul>\n<li><strong>Normal</strong>: sin brillo. La mayoría de cartas de un sobre.</li>\n<li><strong>Holo</strong>: el brillo está <strong>solo en la ilustración</strong>. Es la carta rara clásica de toda la vida.</li>\n<li><strong>Reverse holo</strong>: al revés. El brillo está en <strong>todo menos en la ilustración</strong>. Casi cualquier carta puede tener versión reverse, incluidas las comunes.</li>\n<li><strong>Full art</strong>: la ilustración ocupa la carta entera, sin el marco habitual.</li>\n<li><strong>Alt art</strong> (arte alternativo): una segunda ilustración distinta para una carta que ya existe. Suelen ser las más buscadas y caras del set.</li>\n<li><strong>Rainbow / gold</strong>: acabados especiales, normalmente de las últimas cartas del set.</li>\n</ul>\n\n<h2>Rareza y numeración</h2>\n<ul>\n<li><strong>Secret rare</strong>: una carta cuyo número es <strong>mayor que el total del set</strong>. Si el set tiene 185 cartas y la tuya pone 191/185, es una secret rare.</li>\n<li><strong>1st edition</strong>: sello de primera edición, solo en cartas antiguas. Vale bastante más que la misma carta sin él.</li>\n<li><strong>Shadowless</strong>: cartas muy tempranas del set base a las que les falta la sombra del recuadro de la ilustración.</li>\n</ul>\n\n<h2>Estado de la carta</h2>\n<p>Se usan las siglas en inglés, de mejor a peor:</p>\n<ul>\n<li><strong>M / Mint</strong>: perfecta.</li>\n<li><strong>NM / Near Mint</strong>: prácticamente perfecta. Es lo normal en una carta bien cuidada.</li>\n<li><strong>EX / Excellent</strong>: defectos leves visibles de cerca.</li>\n<li><strong>GD / Good</strong>: desgaste claro.</li>\n<li><strong>PL / Played</strong> y <strong>PO / Poor</strong>: bastante o muy dañada.</li>\n</ul>\n\n<h2>Gradeo</h2>\n<ul>\n<li><strong>Gradear</strong>: mandar una carta a una empresa que la autentica, le pone una nota del 1 al 10 y la sella en una carcasa.</li>\n<li><strong>Slab</strong>: esa carcasa sellada.</li>\n<li><strong>PSA, CGC, BGS/Beckett, SGC</strong>: las casas de gradeo principales.</li>\n<li><strong>Población</strong>: cuántas copias de esa carta han recibido esa nota. Cuanto menor, más escasa.</li>\n</ul>\n\n<h2>Producto sin abrir</h2>\n<ul>\n<li><strong>Sealed</strong>: sellado, sin abrir.</li>\n<li><strong>ETB</strong> (Elite Trainer Box): caja con varios sobres más accesorios.</li>\n<li><strong>Booster box</strong>: caja de sobres, normalmente 36 o 30 según la época.</li>\n<li><strong>Pull</strong>: lo que te sale al abrir. Un <strong>hit</strong> es un pull bueno.</li>\n</ul>\n\n<blockquote>Ojo con \"proxy\": es una reproducción no oficial, hecha para jugar sin gastar. No es una falsificación si se vende como lo que es, pero sí lo es si alguien te la cuela como carta real.</blockquote>"}]'),
  ('leer-una-carta', 'Cómo leer una carta: set, número y rareza', 'Toda la información para identificar cualquier carta está en la franja de abajo. Aprende a leerla y no volverás a preguntar ''qué carta es esta''.', 'card_identification', '🔢', 'beginner', 'bronze', 25, 7, array['identificar', 'rareza', 'sets']::text[], 'identificar carta numero coleccionista simbolo set rareza marca regulacion idioma', '[{"type": "hook", "emoji": "🔢", "headline": "\"¿Qué carta es esta?\" — la respuesta está en la franja de abajo", "subtext": "Cuatro datos y ya puedes identificar y valorar cualquier carta."}, {"type": "quiz", "question": "Tu carta pone 191/185. ¿Qué significa?", "options": ["Es un error de impresión valiosísimo", "Es una secret rare: una carta extra fuera del total del set", "Es una falsificación seguro", "Que el set tiene 191 cartas"], "correct_index": 1, "explanation": "Cuando el número supera el total anunciado del set, es una secret rare: cartas extra que no se cuentan en el total."}, {"type": "match", "title": "Relaciona cada símbolo de rareza con su nivel", "pairs": [{"left": "Círculo ●", "right": "Común"}, {"left": "Rombo ◆", "right": "Infrecuente"}, {"left": "Estrella ★", "right": "Rara"}]}, {"type": "truefalse", "statement": "La letra dentro de un cuadradito (D, E, F...) indica lo rara que es la carta.", "is_true": false, "explanation": "Es la marca de regulación e indica en qué formato de torneo es legal la carta. Para coleccionar es irrelevante; para jugar es lo primero que se mira."}, {"type": "fillblank", "before": "Al buscar el precio de una carta hay que asegurarse de mirar el mismo", "after": "que tienes en la mano, porque no valen lo mismo.", "options": ["idioma", "color", "tamaño", "año"], "correct_option": "idioma", "explanation": "Es el error más común al valorar. Inglés y japonés tienen mercados más grandes; el español tiene su propio público y sus propias escaseces."}, {"type": "checklist", "title": "La ficha de identidad de una carta", "items": ["Número de coleccionista (58/165)", "Símbolo de expansión", "Símbolo de rareza", "Idioma", "Si es holo, reverse holo o normal"]}, {"type": "reward", "next_guide_slug": "mapa-de-rarezas"}]', '[{"type": "richtext", "html": "<h2>Todo está abajo del todo</h2>\n<p>Da igual la época o el idioma: la franja inferior de la carta lleva lo necesario para identificarla sin ninguna duda. Es lo primero que hay que aprender a leer, porque es lo que te permite buscar precios, confirmar que existe y detectar falsificaciones.</p>\n\n<h2>El número de coleccionista</h2>\n<p>Aparece como <em>58/165</em>: la carta 58 de un set de 165. Es el dato más útil de todos.</p>\n<p>Si el primer número es <strong>mayor que el segundo</strong> (por ejemplo 191/185), tienes una <strong>secret rare</strong>: una carta extra que no se cuenta en el total anunciado del set.</p>\n<p>En cartas modernas puede aparecer como <em>058/165</em> con ceros delante, o en sets recientes sin barra, solo el número sobre el total.</p>\n\n<h2>El símbolo de expansión</h2>\n<p>El dibujito pequeño junto al número indica de qué expansión es la carta. Hay cientos, así que nadie se los sabe todos: lo normal es buscarlo. Lo importante es saber que <strong>el símbolo y el número tienen que ser coherentes entre sí</strong>. Un símbolo de un set con un número que en ese set no existe es señal de falsificación.</p>\n\n<h2>El símbolo de rareza</h2>\n<p>Junto al número aparece una figura pequeña:</p>\n<ul>\n<li><strong>Círculo</strong> ● : común.</li>\n<li><strong>Rombo</strong> ◆ : infrecuente.</li>\n<li><strong>Estrella</strong> ★ : rara.</li>\n</ul>\n<p>A partir de ahí, las rarezas superiores (ultra rara, secret rare, ilustración especial) se distinguen por el acabado de la carta y por el número, más que por el símbolo. En los sets más recientes el sistema se ha ampliado con más variantes de estrella.</p>\n\n<h2>La marca de regulación</h2>\n<p>En las cartas modernas hay una <strong>letra dentro de un cuadradito</strong> (D, E, F, G, H...). No tiene que ver con la rareza ni con el valor de colección: indica en qué formato de torneo es legal la carta. Cuando rota el formato, las letras más antiguas dejan de poder jugarse.</p>\n<p>Para coleccionar es irrelevante. Para jugar es lo primero que se mira.</p>\n\n<h2>El idioma y por qué importa</h2>\n<p>Una misma carta existe en muchos idiomas y <strong>no valen lo mismo</strong>. Como norma general el inglés y el japonés tienen mercados más grandes y líquidos. Las cartas en español tienen su propio público, y para ciertas cartas antiguas la versión española es más difícil de encontrar que la inglesa.</p>\n<p>Al buscar precios, asegúrate de estar mirando el mismo idioma que tienes en la mano. Es el error más común al valorar una carta.</p>\n\n<blockquote>Con el número de coleccionista, el set y el idioma ya puedes buscar cualquier carta en cualquier base de datos o mercado. Es la ficha de identidad completa.</blockquote>"}]'),
  ('mapa-de-rarezas', 'Del común al alt art: el mapa de rarezas', 'Por qué dos cartas del mismo Pokémon y el mismo set pueden valer 20 céntimos o 200 euros.', 'card_identification', '✨', 'intermediate', 'silver', 30, 7, array['identificar', 'rareza', 'alt art']::text[], 'rarezas holo reverse full art alt art secret rare rainbow gold diferencia precio', '[{"type": "hook", "emoji": "✨", "headline": "Mismo Pokémon, mismo set: 20 céntimos o 200 euros", "subtext": "La diferencia está en la versión. Aprende a colocarla en el escalón correcto."}, {"type": "order", "title": "Ordena las versiones del escalón más bajo al más alto", "items": ["Normal", "Reverse holo", "Holo", "Ultra rara (V, GX, ex...)", "Full art", "Alt art"]}, {"type": "quiz", "question": "¿Cuál es la forma más fiable de saber si tienes un alt art?", "options": ["Que tenga mucho brillo", "Que el número supere el total del set", "Comparar el dibujo con la versión normal: si la ilustración es otra, es alt art", "Que no tenga marco"], "correct_index": 2, "explanation": "Un alt art es una segunda ilustración completamente distinta de una carta que ya existe. Comparar el dibujo con la versión normal lo resuelve en segundos."}, {"type": "truefalse", "statement": "Si una carta brilla, es valiosa.", "is_true": false, "explanation": "Casi cualquier carta del set tiene versión reverse holo, incluidas las comunes. Que brille no la hace valiosa."}, {"type": "match", "title": "Relaciona cada versión con lo que la identifica", "pairs": [{"left": "Reverse holo", "right": "Brilla todo menos la ilustración"}, {"left": "Holo", "right": "Brilla solo la ilustración"}, {"left": "Full art", "right": "El dibujo ocupa la carta entera, sin marco"}, {"left": "Secret rare", "right": "Su número supera el total del set"}]}, {"type": "reward", "next_guide_slug": "cuanto-vale-tu-carta"}]', '[{"type": "richtext", "html": "<h2>La misma carta, precios muy distintos</h2>\n<p>Un mismo Pokémon en un mismo set puede existir en cinco o seis versiones diferentes. Distinguirlas es lo que separa vender una carta por lo que vale de venderla por céntimos, o pagar de más sin darte cuenta.</p>\n\n<h2>Escalón 1: normal y reverse holo</h2>\n<p>La versión base, sin brillo, y la misma carta con el brillo en <strong>todo menos la ilustración</strong>. La reverse suele valer algo más que la normal, pero en cartas comunes la diferencia es de céntimos.</p>\n<p>Detalle importante: casi cualquier carta del set tiene versión reverse, incluidas las comunes. Que brille no la hace valiosa.</p>\n\n<h2>Escalón 2: holo</h2>\n<p>El brillo está <strong>solo en la ilustración</strong>. Es la rara clásica. En sets antiguos, esta era la carta gorda del sobre; en los modernos hay bastantes escalones por encima.</p>\n\n<h2>Escalón 3: las ultra raras</h2>\n<p>Cartas con mecánicas especiales según la época (EX, GX, V, VMAX, ex...). Suelen venir con acabados llamativos y son las que la gente busca al abrir sobres.</p>\n\n<h2>Escalón 4: full art</h2>\n<p>La ilustración ocupa <strong>toda la carta</strong>, sin el marco habitual y con textura en relieve. Salen con mucha menos frecuencia que las anteriores.</p>\n\n<h2>Escalón 5: alt art (arte alternativo)</h2>\n<p>Aquí está el dinero. Un alt art es una <strong>segunda ilustración completamente distinta</strong> para una carta que ya existe en el set, normalmente con una escena elaborada en lugar del retrato del Pokémon.</p>\n<p>Salen muy poco y son las más deseadas: en muchos sets modernos, el alt art más buscado vale más que todo el resto del set junto. Si dudas si tu carta es un alt art, compara la ilustración con la versión normal de esa misma carta: si el dibujo es otro, ahí lo tienes.</p>\n\n<h2>Escalón 6: rainbow, gold y secret rares</h2>\n<p>Los últimos números del set, por encima del total anunciado. Acabados de arcoíris o dorado. Históricamente muy caras; en los sets más recientes su valor se ha moderado bastante frente a los alt art, que se han comido el protagonismo.</p>\n\n<h2>Cómo saber en qué escalón estás</h2>\n<ol>\n<li>Mira el número: si supera el total del set, es secret rare.</li>\n<li>Mira si el brillo está en la ilustración (holo) o fuera (reverse).</li>\n<li>Mira si hay marco: sin marco es full art.</li>\n<li>Compara el dibujo con la versión normal: si es distinto, es alt art.</li>\n</ol>\n\n<blockquote>Antes de vender, comprueba siempre en qué versión estás. Vender un alt art al precio de la holo normal es el error más caro que se comete en esta afición.</blockquote>"}]'),
  ('cuanto-vale-tu-carta', 'Cuánto vale tu carta de verdad', 'El precio que pide alguien no es el precio de mercado. Cómo mirar ventas reales y no llevarte una decepción.', 'market_and_trading', '💶', 'beginner', 'bronze', 30, 8, array['mercado', 'precios', 'vender']::text[], 'cuanto vale precio carta cardmarket ebay ventas tasar valorar mercado', '[{"type": "hook", "emoji": "💶", "headline": "Has visto tu carta anunciada a 300 €. ¿Vale 300 €?", "subtext": "Ni de lejos, necesariamente. Vamos a separar lo que alguien pide de lo que la gente paga."}, {"type": "truefalse", "statement": "El precio ''desde'' de Cardmarket es lo que vale tu carta.", "is_true": false, "explanation": "El ''desde'' es el anuncio más barato, normalmente de peor estado o de un vendedor lejano. La cifra útil es el precio de tendencia, que sale de ventas reales."}, {"type": "quiz", "question": "En eBay, ¿qué hay que filtrar para ver precios reales?", "options": ["Los artículos en venta", "Los artículos vendidos", "Los que tienen envío gratis", "Los de vendedores con más valoraciones"], "correct_index": 1, "explanation": "Los artículos en venta son precios de pedida. Solo los vendidos son transacciones cerradas de verdad."}, {"type": "order", "title": "Ordena el método para tasar una carta", "items": ["Identificar set, número, versión e idioma", "Buscarla en Cardmarket y mirar el precio de tendencia", "Filtrar por el estado real de tu carta", "Contrastar con ventas cerradas en eBay", "Restar comisiones y envío si vas a venderla"]}, {"type": "match", "title": "Relaciona cada factor con su efecto en el precio", "pairs": [{"left": "Versión (alt art vs normal)", "right": "Es lo que más pesa, con diferencia"}, {"left": "Estado", "right": "Entre impecable y jugada hay una diferencia enorme"}, {"left": "Idioma", "right": "La misma carta no vale igual en cada uno"}, {"left": "Gradeo", "right": "Una nota alta la mete en otra liga"}]}, {"type": "truefalse", "statement": "Si tienes prisa por vender, normalmente cobrarás menos.", "is_true": true, "explanation": "Vender rápido casi siempre implica bajar el precio. En esta afición la paciencia es literalmente dinero."}, {"type": "reward", "next_guide_slug": "comprar-seguro-segunda-mano"}]', '[{"type": "richtext", "html": "<h2>El malentendido de partida</h2>\n<p>Buscas tu carta, ves un anuncio a 300 € y das por hecho que vale 300 €. No: eso es lo que <strong>alguien pide</strong>. Cualquiera puede pedir lo que quiera. El precio real es lo que la gente <strong>ha pagado</strong>, y no siempre son parecidos.</p>\n<blockquote>Precio de pedida ≠ precio de mercado. Toda la valoración se apoya en esta distinción.</blockquote>\n\n<h2>Dónde mirar, en España y Europa</h2>\n<p><strong>Cardmarket</strong> es la referencia principal en Europa. Lo importante es entender qué te está enseñando:</p>\n<ul>\n<li><strong>Desde</strong>: el anuncio más barato. Suele ser de peor estado o de un vendedor lejano. No es el valor de tu carta.</li>\n<li><strong>Precio de tendencia</strong>: una media ponderada de ventas reales recientes. <strong>Esta es la cifra útil.</strong></li>\n<li><strong>Media de 30 días</strong>: aún más estable, buena para cartas que se mueven poco.</li>\n</ul>\n<p>En <strong>eBay</strong>, la clave es filtrar por <em>artículos vendidos</em>, no por los que están en venta. Ahí ves transacciones cerradas de verdad.</p>\n\n<h2>Los cuatro factores que mueven el precio</h2>\n<ol>\n<li><strong>Versión</strong>: normal, reverse, holo, full art, alt art. Es lo que más pesa, con diferencia.</li>\n<li><strong>Estado</strong>: entre una carta impecable y una jugada puede haber una diferencia enorme. Sé honesto contigo mismo al evaluarla; casi todo el mundo sobrevalora sus cartas.</li>\n<li><strong>Idioma</strong>: busca precios del mismo idioma que tienes.</li>\n<li><strong>Gradeo</strong>: una carta graduada con nota alta juega en otra liga. Una sin graduar se valora como \"en bruto\".</li>\n</ol>\n\n<h2>Un método de 3 minutos</h2>\n<ol>\n<li>Identifica la carta con exactitud: set, número, versión, idioma.</li>\n<li>Búscala en Cardmarket y mira el <strong>precio de tendencia</strong>, no el \"desde\".</li>\n<li>Filtra por tu estado real.</li>\n<li>Contrasta con ventas cerradas de eBay.</li>\n<li>Si vas a vender, cuenta comisiones y envío antes de decidir si te compensa.</li>\n</ol>\n\n<h2>Expectativas realistas</h2>\n<p>La inmensa mayoría de las cartas valen muy poco, incluidas muchas que brillan. Eso no las hace menos bonitas ni menos tuyas. Las cartas caras son la excepción, no la norma, y una colección no deja de tener valor por no estar llena de ellas.</p>\n<p>Y al vender: si tienes prisa, cobrarás menos. La paciencia es, literalmente, dinero.</p>"}]'),
  ('comprar-seguro-segunda-mano', 'Comprar seguro en Wallapop, Vinted y eBay', 'Dónde están las gangas de verdad y cómo no acabar con un lote de falsificaciones y sin poder reclamar.', 'market_and_trading', '🛡️', 'beginner', 'silver', 30, 8, array['mercado', 'comprar', 'seguridad', 'estafas']::text[], 'comprar seguro wallapop vinted ebay estafa bizum segunda mano reclamar', '[{"type": "hook", "emoji": "🛡️", "headline": "\"Te lo dejo más barato si me pagas por Bizum\"", "subtext": "No es un descuento. Es el precio de que no puedas reclamar nada."}, {"type": "truefalse", "statement": "Pagar por Bizum fuera de la plataforma es aceptable si el vendedor tiene buenas valoraciones.", "is_true": false, "explanation": "Al salir de la plataforma renuncias a toda protección, tenga las valoraciones que tenga. Si el paquete no llega o llega con falsificaciones, no hay a quién reclamar."}, {"type": "quiz", "question": "Dudas de que las fotos del anuncio sean del vendedor. ¿Qué le pides?", "options": ["Que te jure que son suyas", "Una foto de la carta junto a un papel con tu nombre y la fecha escritos a mano", "Que suba más fotos de internet", "El número de teléfono"], "correct_index": 1, "explanation": "Es la comprobación estándar y demuestra que tiene la carta físicamente. Un vendedor honesto la hace sin problema."}, {"type": "checklist", "title": "Fotos que hay que pedir antes de pagar", "items": ["El reverso de la carta", "La carta en ángulo bajo una luz", "Las cuatro esquinas, si es cara", "El número de certificado legible, si es un slab", "La carta junto a un papel con tu nombre y la fecha"]}, {"type": "fillblank", "before": "Al recibir el paquete conviene", "after": "abriéndolo en un plano continuo, porque es la mejor prueba si hay problema.", "options": ["grabarte", "pesarlo", "abrirlo rápido", "confirmar la recepción"], "correct_option": "grabarte", "explanation": "Un vídeo continuo desde que el paquete está cerrado es la prueba más sólida en una reclamación."}, {"type": "truefalse", "statement": "Conviene confirmar la recepción en la app cuanto antes, por educación.", "is_true": false, "explanation": "Al confirmar sueltas el dinero y pierdes casi toda la capacidad de reclamar. Revisa la compra a fondo antes de confirmar."}, {"type": "match", "title": "Relaciona cada señal de alerta con lo que suele esconder", "pairs": [{"left": "Precio muy por debajo de mercado", "right": "Falsificación o estafa"}, {"left": "\"Decídete ya, hay más gente\"", "right": "Prisa para que no compruebes"}, {"left": "Perfil creado hace tres días", "right": "Cuenta desechable"}, {"left": "\"Carta rara Charizard\" sin set", "right": "No sabe o no quiere decir qué vende"}]}, {"type": "reward", "next_guide_slug": "como-se-juega-en-5-minutos"}]', '[{"type": "richtext", "html": "<h2>La regla que resume todo</h2>\n<p><strong>Paga siempre dentro de la plataforma.</strong> Es la única frase que de verdad hay que memorizar.</p>\n<p>Cuando pagas por Bizum o transferencia a alguien que has conocido en una app de compraventa, estás renunciando voluntariamente a toda protección. Si el paquete no llega, o llega con cartas falsas, o llega vacío, no hay a quién reclamar. Es exactamente por eso que te lo proponen.</p>\n<blockquote>\"Te lo dejo más barato si me pagas por Bizum y quedamos fuera de la app\" no es un descuento. Es el precio de que no puedas reclamar.</blockquote>\n\n<h2>Revisar al vendedor antes que el producto</h2>\n<ul>\n<li><strong>Antigüedad y valoraciones</strong>: un perfil creado hace tres días con cartas caras es una señal muy mala.</li>\n<li><strong>Qué más vende</strong>: un perfil coherente (ropa, muebles, y de repente cartas por 400 €) no cuadra.</li>\n<li><strong>Valoraciones negativas</strong>: léelas, no te quedes en la nota media.</li>\n</ul>\n\n<h2>Las fotos lo dicen casi todo</h2>\n<p>Exige <strong>fotos reales de la carta concreta</strong>, no imágenes sacadas de internet. Si dudas de que las fotos sean suyas, pide una foto de la carta <strong>junto a un papel con tu nombre y la fecha escritos a mano</strong>. Es la comprobación estándar y un vendedor honesto la hace sin problema.</p>\n<p>Pide además:</p>\n<ul>\n<li>Foto del <strong>reverso</strong>: delata muchas falsificaciones y muestra el centrado.</li>\n<li>Foto <strong>en ángulo bajo una luz</strong>: revela arañazos, dobleces y el patrón del holo.</li>\n<li>Foto de las <strong>cuatro esquinas</strong> si la carta es cara.</li>\n<li>En slabs, foto del <strong>número de certificado</strong> legible, para verificarlo tú.</li>\n</ul>\n\n<h2>Señales de alerta</h2>\n<ul>\n<li>Precio muy por debajo del mercado sin explicación.</li>\n<li>Prisa: \"tengo más gente interesada, decídete ya\".</li>\n<li>Negativa a mandar fotos adicionales.</li>\n<li>Descripciones vagas: \"carta rara Charizard\" sin set ni número.</li>\n<li>Lotes grandes de cartas caras con fotos de baja calidad y amontonadas.</li>\n<li>Insistencia en salir de la plataforma.</li>\n</ul>\n\n<h2>Cuando llega el paquete</h2>\n<p><strong>Grábate abriéndolo</strong>, en un plano continuo y sin cortes, desde que el paquete está cerrado. Si hay problema, ese vídeo es tu mejor prueba. Y revisa la compra antes de confirmar la recepción en la app: una vez confirmas, sueltas el dinero y pierdes casi toda la capacidad de reclamar.</p>\n\n<h2>Y si te la cuelan</h2>\n<p>Abre la incidencia dentro de la plataforma y en plazo, con fotos y el vídeo. Después, avisa a la comunidad: el aviso a tiempo evita que caiga alguien más.</p>"}]'),
  ('como-se-juega-en-5-minutos', 'Cómo se juega, en 5 minutos', 'Las reglas mínimas para echar tu primera partida. Sin manual de 40 páginas.', 'play_pokemon', '🎮', 'beginner', 'bronze', 25, 6, array['jugar', 'reglas', 'primeros pasos']::text[], 'como se juega reglas partida premios banquillo energia evolucion retirada', '[{"type": "hook", "emoji": "🎮", "headline": "Tienes cartas pero nunca has jugado", "subtext": "Cinco minutos y ya puedes echar tu primera partida. Sin manual de 40 páginas."}, {"type": "quiz", "question": "¿Cuál es la forma más habitual de ganar una partida?", "options": ["Que el rival se quede sin cartas en la mano", "Coger tus 6 cartas de Premio", "Tener más energías en juego", "Debilitar al Pokémon Activo tres veces"], "correct_index": 1, "explanation": "Coges un Premio cada vez que debilitas un Pokémon rival. Casi todas las partidas se deciden así."}, {"type": "order", "title": "Ordena las fases de tu turno", "items": ["Robar una carta", "Poner básicos, evolucionar y jugar Entrenadores", "Adjuntar una energía", "Atacar (y terminar el turno)"]}, {"type": "truefalse", "statement": "Si tienes tres energías en la mano, puedes adjuntar las tres en un turno.", "is_true": false, "explanation": "Solo una energía por turno. Es el límite que marca el ritmo de toda la partida: un ataque de tres energías tarda al menos tres turnos en estar listo."}, {"type": "truefalse", "statement": "Puedes evolucionar un Pokémon el mismo turno en que lo pones en juego.", "is_true": false, "explanation": "Hay que esperar al turno siguiente, y tampoco se puede evolucionar en tu primer turno de la partida."}, {"type": "match", "title": "Relaciona cada zona con lo que hace", "pairs": [{"left": "Pokémon Activo", "right": "El único que ataca y recibe ataques"}, {"left": "Banquillo", "right": "Hasta 5 Pokémon esperando y cargando energía"}, {"left": "Premios", "right": "6 cartas que coges al debilitar rivales"}, {"left": "Coste de retirada", "right": "Energías a descartar para cambiar de Activo"}]}, {"type": "fillblank", "before": "Si el defensor tiene", "after": "al tipo del atacante, el daño se multiplica, normalmente por dos.", "options": ["debilidad", "resistencia", "coste de retirada", "una herramienta"], "correct_option": "debilidad", "explanation": "La resistencia hace lo contrario: resta una cantidad fija de daño. Mirar la debilidad del rival antes de elegir Activo decide muchas partidas."}, {"type": "reward", "next_guide_slug": "tu-primer-mazo"}]', '[{"type": "richtext", "html": "<h2>Cómo se gana</h2>\n<p>Hay tres formas, y basta con cumplir una:</p>\n<ol>\n<li>Coger tus <strong>6 cartas de Premio</strong> (una cada vez que debilitas un Pokémon rival).</li>\n<li>Que el rival <strong>se quede sin Pokémon</strong> en juego.</li>\n<li>Que el rival <strong>no pueda robar</strong> carta al empezar su turno.</li>\n</ol>\n<p>Casi todas las partidas se deciden por la primera.</p>\n\n<h2>La mesa</h2>\n<ul>\n<li><strong>Pokémon Activo</strong>: el que está al frente. Solo él ataca y solo a él le atacan.</li>\n<li><strong>Banquillo</strong>: hasta 5 Pokémon esperando. No atacan, pero pueden ir cargando energías.</li>\n<li><strong>Premios</strong>: 6 cartas boca abajo que vas cogiendo al debilitar rivales.</li>\n<li><strong>Pila de descarte</strong>: donde va lo usado y lo debilitado.</li>\n</ul>\n\n<h2>Tu turno, en orden</h2>\n<ol>\n<li><strong>Robas</strong> una carta. Si no puedes, pierdes.</li>\n<li>Haces lo que quieras de esto, en el orden que quieras: poner Pokémon Básicos en el banquillo, evolucionar, jugar cartas de Entrenador, retirar al Activo.</li>\n<li><strong>Adjuntas una energía</strong>. Solo una por turno: es el límite que marca el ritmo de toda la partida.</li>\n<li><strong>Atacas</strong>. Atacar termina tu turno inmediatamente.</li>\n</ol>\n\n<h2>Las tres cosas que más se lían al empezar</h2>\n<h3>Una energía por turno</h3>\n<p>No importa cuántas tengas en la mano: solo puedes adjuntar una por turno. Por eso un ataque que pide tres energías tarda al menos tres turnos en estar listo, y por eso conviene ir cargando también a alguien del banquillo.</p>\n\n<h3>Evolucionar no es instantáneo</h3>\n<p>Un Pokémon <strong>no puede evolucionar el mismo turno en que lo pones</strong> en juego, ni en tu primer turno de la partida. La evolución se pone encima y conserva daño y energías.</p>\n\n<h3>Retirarse cuesta</h3>\n<p>Cambiar a tu Activo por uno del banquillo cuesta descartar tantas energías como indique el <strong>coste de retirada</strong> de la carta (abajo del todo). Solo puedes retirarte una vez por turno.</p>\n\n<h2>Debilidad y resistencia</h2>\n<p>Si el defensor tiene <strong>debilidad</strong> al tipo del atacante, el daño se multiplica (normalmente ×2). Si tiene <strong>resistencia</strong>, se resta una cantidad fija. Esto decide muchísimas partidas: mirar la debilidad del rival antes de elegir a quién mandas al frente es de las cosas que más se notan al empezar.</p>\n\n<blockquote>Consejo real: en tu primera partida no intentes recordarlo todo. Juega con las cartas delante y consulta. Todo el mundo lo hace.</blockquote>"}]'),
  ('tu-primer-mazo', 'Tu primer mazo: la proporción que funciona', 'Por qué un mazo con tus 60 cartas favoritas no gana nunca, y qué proporción usar en su lugar.', 'play_pokemon', '🃏', 'intermediate', 'silver', 30, 7, array['jugar', 'mazos', 'estrategia']::text[], 'primer mazo construir 60 cartas proporcion consistencia lineas evolutivas', '[{"type": "hook", "emoji": "🃏", "headline": "Tus 60 cartas favoritas no son un mazo", "subtext": "Un mazo es una máquina que hace una cosa de forma fiable. Vamos con la proporción que funciona."}, {"type": "quiz", "question": "¿Cuántas copias de una misma carta puedes llevar?", "options": ["2, salvo las energías básicas", "4, salvo las energías básicas que no tienen límite", "4, sin excepciones", "Las que quieras"], "correct_index": 1, "explanation": "Máximo 4 por nombre, y las energías básicas son la excepción: de esas puedes llevar las que quieras."}, {"type": "truefalse", "statement": "Un mazo debe llevar más Pokémon que cartas de Entrenador.", "is_true": false, "explanation": "Al revés. Los Entrenadores son los que te dejan robar y buscar lo que necesitas; sin ellos dependes de la suerte del robo. Una proporción típica es ~16 Pokémon y ~30 Entrenadores."}, {"type": "fillblank", "before": "Una línea evolutiva debe estar equilibrada en", "after": ": más básicos que evoluciones, o casi nunca podrás evolucionar.", "options": ["pirámide", "partes iguales", "orden inverso", "parejas"], "correct_option": "pirámide", "explanation": "Con 4 de la primera fase y solo 1 de la segunda, la evolución casi nunca aparece cuando la necesitas."}, {"type": "truefalse", "statement": "Meter cinco líneas evolutivas distintas hace el mazo más versátil.", "is_true": false, "explanation": "Lo dispersa. Con tantas líneas ninguna llega a tiempo. Dos como mucho."}, {"type": "order", "title": "Ordena los pasos para mejorar un mazo que ya has jugado", "items": ["Jugar varias partidas con él", "Apuntar qué carta te habría gustado tener en cada momento perdido", "Quitar las cartas que casi nunca has llegado a jugar", "Probar la mano inicial diez veces seguidas para ver si el plan arranca"]}, {"type": "reward", "next_guide_slug": "1999-como-empezo-todo"}]', '[{"type": "richtext", "html": "<h2>El error clásico</h2>\n<p>Coger las 60 cartas que más te gustan y meterlas en un mazo. El resultado es siempre el mismo: partidas en las que no te sale nada de lo que necesitas, porque llevas veinte planes distintos y ninguno completo.</p>\n<p>Un mazo no es una colección. Es una <strong>máquina que tiene que hacer una cosa concreta de forma fiable</strong>.</p>\n\n<h2>Las reglas que no se negocian</h2>\n<ul>\n<li>Exactamente <strong>60 cartas</strong>. Ni 59 ni 61.</li>\n<li>Máximo <strong>4 copias</strong> de una misma carta por nombre. Excepción: las <strong>energías básicas</strong>, que no tienen límite.</li>\n<li>Al menos un Pokémon <strong>Básico</strong>, o no puedes ni empezar la partida.</li>\n</ul>\n\n<h2>Una proporción que funciona al empezar</h2>\n<p>No es sagrada, pero como punto de partida es sólida:</p>\n<ul>\n<li><strong>~14-18 Pokémon</strong></li>\n<li><strong>~28-32 Entrenadores</strong></li>\n<li><strong>~10-14 Energías</strong></li>\n</ul>\n<p>A casi todos los principiantes les sorprende que haya <strong>más Entrenadores que Pokémon</strong>. Es justo lo que separa un mazo que funciona de uno que no: los Entrenadores son los que te dejan robar cartas y buscar exactamente lo que necesitas. Sin ellos dependes de la suerte del robo.</p>\n\n<h2>Líneas evolutivas: el fallo más común</h2>\n<p>Si llevas 4 de la fase 1 y solo 1 de la fase 2, casi nunca vas a poder evolucionar. La línea tiene que estar <strong>equilibrada y en pirámide</strong>: más básicos que evoluciones.</p>\n<p>Para una línea de dos fases, algo como 4 básicos / 3 evoluciones funciona. Y un consejo mayor: <strong>no metas cinco líneas evolutivas distintas</strong>. Dos como mucho, o el mazo se dispersa y ninguna llega a tiempo.</p>\n\n<h2>Consistencia por encima de todo</h2>\n<p>Es la palabra clave. Un mazo consistente es el que hace lo que quiere hacer <strong>casi todas las partidas</strong>, no el que tiene la jugada más espectacular una de cada diez.</p>\n<p>Prueba práctica: baraja y roba siete cartas, diez veces seguidas. Si en la mayoría de esas manos puedes empezar a montar tu plan, vas bien. Si en la mitad te quedas mirando cartas que no encajan, sobran cosas.</p>\n\n<h2>Cómo mejorarlo después</h2>\n<p>Juega y apunta qué carta te habría gustado tener en cada momento perdido. Después quita lo que casi nunca has jugado. Un mazo mejora mucho más <strong>quitando cartas mediocres</strong> que añadiendo cartas buenas.</p>\n\n<blockquote>Si tienes que elegir entre una carta espectacular que sale poco y una carta discreta que sale siempre, coge la discreta. Ganan las partidas los mazos aburridos y fiables.</blockquote>"}]'),
  ('1999-como-empezo-todo', '1999: cómo empezó todo', 'El Set Base, la primera edición y por qué un Charizard de cartón se convirtió en leyenda.', 'history', '🔥', 'beginner', 'gold', 25, 7, array['historia', 'set base', 'primera edicion']::text[], '1999 set base charizard primera edicion shadowless wizards historia origen', '[{"type": "hook", "emoji": "🔥", "headline": "El Charizard más famoso del mundo era una carta mediocre", "subtext": "Y aun así se convirtió en leyenda. Vamos a ver por qué, y qué mirar si tienes cartas de 1999."}, {"type": "quiz", "question": "¿Qué empresa distribuyó el primer set en Occidente, en 1999?", "options": ["Nintendo", "Media Factory", "Wizards of the Coast", "Creatures Inc."], "correct_index": 2, "explanation": "Wizards of the Coast, la misma empresa detrás de Magic. En Japón el juego había nacido en 1996 con Media Factory."}, {"type": "truefalse", "statement": "El Charizard del Set Base era una de las mejores cartas para jugar.", "is_true": false, "explanation": "Su ataque pedía cuatro energías de fuego y obligaba a descartar dos. Nunca fue competitivo: su leyenda es cultural, no de juego."}, {"type": "order", "title": "Ordena las variantes del Set Base por orden de tirada", "items": ["Primera edición (con sello negro)", "Shadowless (sin sello y sin sombra)", "Unlimited (con sombra, tirada masiva)"]}, {"type": "match", "title": "Relaciona cada variante con cómo se reconoce", "pairs": [{"left": "Primera edición", "right": "Sello negro con un ''1'' junto a la ilustración"}, {"left": "Shadowless", "right": "Sin sello y sin sombra a la derecha del recuadro"}, {"left": "Unlimited", "right": "Con sombra y sin sello: la tirada masiva"}]}, {"type": "fillblank", "before": "Buena parte del mercado actual se explica por la", "after": ": los niños de 1999 son los adultos con sueldo que compran hoy.", "options": ["nostalgia", "escasez", "especulación", "publicidad"], "correct_option": "nostalgia", "explanation": "Es el motor de fondo del coleccionismo moderno, y explica por qué el Set Base tiene un peso que ningún set nuevo consigue replicar."}, {"type": "reward", "next_guide_slug": ""}]', '[{"type": "richtext", "html": "<h2>El principio</h2>\n<p>El juego de cartas nació en Japón en 1996, de la mano de Media Factory, después del éxito de los videojuegos. Funcionó tan bien que se planteó sacarlo fuera, y en <strong>1999</strong> llegó la versión occidental, distribuida por <strong>Wizards of the Coast</strong>, la misma empresa detrás de Magic.</p>\n<p>Ese primer set es el que todo el mundo conoce como <strong>Set Base</strong>: 102 cartas, con los tres iniciales de Kanto en sus formas finales como grandes reclamos.</p>\n\n<h2>Por qué el Charizard</h2>\n<p>Varias cosas coincidieron a la vez, y por eso no ha vuelto a pasar igual con ninguna otra carta:</p>\n<ul>\n<li>Era el Pokémon <strong>más deseado</strong> del videojuego para toda una generación.</li>\n<li>Tenía <strong>120 HP</strong>, una barbaridad para la época.</li>\n<li>Salía <strong>muy poco</strong>: era la carta gorda del set.</li>\n<li>Y sobre todo: los niños que la querían en 1999 son los adultos con sueldo que la compran ahora. Buena parte del mercado actual es nostalgia con poder adquisitivo.</li>\n</ul>\n<p>Detalle irónico que le encanta a la gente que sí jugaba: como carta de juego el Charizard del Set Base <strong>no era muy bueno</strong>. Su ataque pedía cuatro energías de fuego y encima obligaba a descartar dos. Nunca fue una carta competitiva. Su leyenda es puramente cultural.</p>\n\n<h2>Las variantes que disparan el precio</h2>\n<p>Dentro del propio Set Base hay versiones que valen muchísimo más que otras. Por orden de aparición en la imprenta:</p>\n\n<h3>Primera edición</h3>\n<p>Llevan un <strong>sello negro pequeño</strong> con un \"1\" a la izquierda de la ilustración. Corresponden a la primerísima tirada, muy corta. Es la variante más buscada.</p>\n\n<h3>Shadowless</h3>\n<p>Justo después de la primera edición, y antes de la tirada normal, hubo copias <strong>sin el sello</strong> pero que aún conservaban el diseño temprano: <strong>sin la sombra</strong> a la derecha del recuadro de la ilustración. Se llaman <em>shadowless</em> y están en un escalón intermedio de valor.</p>\n\n<h3>Unlimited</h3>\n<p>La tirada masiva, ya con sombra y sin sello. Es la que tuvo casi todo el mundo, y por eso la más asequible hoy.</p>\n\n<blockquote>Si tienes cartas del Set Base guardadas, lo primero que hay que mirar es si llevan el sello de primera edición y si tienen sombra a la derecha del recuadro. Ahí puede haber una diferencia de precio muy grande entre dos cartas que parecen idénticas.</blockquote>\n\n<h2>Y en español</h2>\n<p>El Set Base también salió en español, y para ciertas cartas las tiradas fueron notablemente menores que las inglesas. Eso hace que algunas versiones españolas sean más difíciles de encontrar en buen estado de lo que la gente supone.</p>"}]'),
  ('sellado-resellado', 'Producto sellado: detectar un resellado', 'Cajas y ETB reprecintadas a las que les han sacado las cartas buenas. Qué mirar antes de pagar.', 'fake_detection', '📦', 'intermediate', 'silver', 35, 7, array['falsificaciones', 'sellado', 'etb', 'booster box']::text[], 'sellado resellado etb booster box precinto plastico weighing pesar sobres', '[{"type": "hook", "emoji": "📦", "headline": "Llega sellado. Pero, ¿sellado por quién?", "subtext": "Retractilar una caja en casa cuesta cuatro duros. Vamos a ver cómo se nota."}, {"type": "concept", "emoji": "🔁", "title": "En qué consiste el resellado", "body": "Abrir una caja o ETB, sacar los sobres, quitarles las cartas buenas o cambiarlos por sobres de un set más barato, y volver a precintar el conjunto con una máquina de retractilado.", "highlight": "No hace falta falsificar nada: el producto es real, lo que falta es el contenido valioso."}, {"type": "match", "title": "Relaciona cada parte del precinto con lo que la delata", "pairs": [{"left": "Costuras", "right": "Desplazadas, gruesas o en un sitio raro"}, {"left": "Esquinas", "right": "Pliegues abultados o arrugados"}, {"left": "Superficie", "right": "Zonas mate o con burbujas del secador"}, {"left": "Tacto", "right": "Plástico grueso que ''flota'' sobre la caja"}]}, {"type": "truefalse", "statement": "Pesar sobres sueltos sigue siendo una forma fiable de saber cuáles llevan carta buena.", "is_true": false, "explanation": "Era conocida hace años, pero los fabricantes tomaron medidas y hoy es mucho menos fiable. Lo importante es al revés: unos sobres sueltos a granel pueden haber sido pesados y descartados antes de llegar a ti."}, {"type": "quiz", "question": "¿Cuál es el producto con más riesgo del mercado?", "options": ["Los ETB de tienda oficial", "Las cajas de sobres precintadas de distribuidor", "Los sobres sueltos de origen dudoso", "Las cartas sueltas graduadas"], "correct_index": 2, "explanation": "Un sobre suelto sin trazabilidad puede haber sido pesado, abierto y vuelto a cerrar, o cambiado por otro set. No hay forma de saberlo por fuera."}, {"type": "checklist", "title": "Antes de pagar un sellado de particular", "items": ["Fotos del precinto por los cuatro lados", "Foto de cerca de las costuras del plástico", "Comprobar que no hay restos de pegamento ni cinta", "Mirar si la caja tiene marcas de haber sido abierta", "Grabarte abriendo el paquete al recibirlo"]}, {"type": "reward", "next_guide_slug": "empezar-coleccion-sin-arruinarte"}]', '[{"type": "richtext", "html": "<h2>El fraude</h2>\n<p>No hace falta falsificar nada: basta con abrir una caja o un ETB, sacar los sobres, quitarles las cartas buenas o sustituirlos por sobres de otro set más barato, y <strong>volver a precintar</strong> el conjunto con una máquina de retractilado que cuesta muy poco.</p>\n<p>El comprador paga precio de producto sellado y recibe una caja vacía de contenido valioso. Y como llega \"sellada\", muchas veces ni sospecha.</p>\n\n<h2>El plástico lo delata</h2>\n<p>El retractilado de fábrica es muy uniforme. El casero, casi nunca. Mira:</p>\n<ul>\n<li><strong>Las costuras</strong>: en fábrica van en posiciones consistentes y quedan finas. Un resellado suele tener la costura desplazada, gruesa o en un sitio raro.</li>\n<li><strong>Los pliegues de las esquinas</strong>: los originales son limpios y simétricos. Los caseros quedan abultados o arrugados.</li>\n<li><strong>El grosor y el tacto</strong>: el plástico de fábrica suele ser más fino y ceñido. Un plástico más grueso o que \"flota\" sobre la caja es mala señal.</li>\n<li><strong>Zonas mate, quemadas o con burbujas</strong>: rastro del secador de calor.</li>\n<li><strong>Restos de pegamento o cinta</strong>: nunca deberían estar ahí.</li>\n</ul>\n\n<h2>La caja por debajo del plástico</h2>\n<p>Muchos productos llevan además pegatinas o solapas de seguridad propias. Comprueba que no estén cortadas y vueltas a pegar. Y fíjate en si la caja tiene <strong>marcas de haber sido abierta</strong>: solapas cansadas, cartón con doblez, esquinas reventadas.</p>\n\n<h2>El peso</h2>\n<p>Pesar el producto y compararlo con uno del que te fíes es útil, sobre todo si faltan sobres enteros o los han cambiado por otros. No es infalible, pero un desvío grande es concluyente.</p>\n<p>Sobre <em>pesar sobres sueltos</em> para adivinar cuáles llevan carta buena: era una técnica conocida hace años, los fabricantes tomaron medidas y hoy es mucho menos fiable. Lo relevante para ti es al revés: <strong>si te venden sobres sueltos a granel, pueden haber sido pesados y descartados antes</strong>. Los sobres sueltos de origen dudoso son el producto con más riesgo del mercado.</p>\n\n<blockquote>Regla simple: cuanto más lejos esté el producto de una tienda con distribución oficial, más importa el examen del precinto. Un ETB sellado a mitad de precio de un particular sin valoraciones es justo el escenario del que hablamos.</blockquote>\n\n<h2>Dónde comprar sellado con tranquilidad</h2>\n<p>Tiendas con distribución oficial y establecimientos conocidos. Si compras de particular, pide <strong>fotos del precinto por los cuatro lados y de las costuras</strong>, y grábate abriendo el paquete al recibirlo.</p>"}]')
) as s(
  slug, title, description, category_slug, cover_emoji, level, guide_rarity,
  xp_reward, estimated_mins, tags, search_content, blocks, reference_blocks
)
join categories c on c.slug = s.category_slug
on conflict (slug) do nothing;

-- Recuenta las guías publicadas de cada categoría.
update categories c
set guide_count = (
  select count(*) from guides g
  where g.category_id = c.id and g.published_at is not null
);

commit;

-- Comprobación rápida: debería salir una fila por categoría con su
-- número de guías actualizado.
select c.slug, c.name, c.guide_count
from categories c
order by c.order_pos;
